import{z as o,x as s,o as e,c as d,q as r,j as t,D as a,d as B,s as l,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"可解释性引导的训练","description":"","frontmatter":{"title":"可解释性引导的训练","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-guided-training.md","filePath":"llm/xai-guided-training.md","lastUpdated":1791063341000}'),D={name:"llm/xai-guided-training.md"};function p(C,E,F,m,u,f){const i=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="可解释性引导的训练" tabindex="-1">可解释性引导的训练 <a class="header-anchor" href="#可解释性引导的训练" aria-label="Permalink to &quot;可解释性引导的训练&quot;">​</a></h1><div class="epigraph"><p>监控是读，训练是写；解释性从诊断室走进训练房，才算真正参与塑造模型，而不只是给模型拍片子。</p><footer>—— 据 Zou et al., 2023 的 rerouting 思路与 Arditi et al., 2024 的方向中介结果整理</footer></div><p><a href="/llm/xai-deception-monitoring">上一课</a>把内部读数接进监控：问题被检测出来，交回去修。本课往前一步：把内部读数直接写进训练目标，让解释性从诊断变成塑形工具。常规对齐改的是输出分布，中间表征可以原封不动地保持「随时能续写」的能力——<a href="/llm/specification-gaming">规约博弈</a>的缝隙因此在表征里留门。本课写读数回写训练的三条注入点：数据、损失、消融，以及每条的验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表征级训练的问题化有三问。把哪些内部量写进目标：特征读数、方向坐标还是区域约束；写进去会不会伤能力：残差流是共享总线，对有害区施力难免蹭到无害任务；引导之后怎么验收：不能只看目标行为改善，要按第 2 课协议重跑特征画像，看有没有把问题挤进字典没覆盖的子空间。三问的公共背景是：训练目标一旦写成表征级，就比输出级目标更难逃逸，也更难审计——力量越大，验收责任越重。</p><p><span class="marginnote">「残差流是共享总线」用类比理解：残差流像全公司共用的公告板，每个组件都往上贴信息、也都从上面读。安全团队往板上某块区域施力（压低有害方向的读数），读板的不只是有害内容——无害任务可能被一并蹭伤，这就是后面说的「能力税」。约束越狠，税越重。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>数据级注入。</strong> 用特征画像筛数据：以第 5 课的监控读数扫描训练语料与生成的候选样本，把高欺骗读数的样本簇定位出来，要么剔除、要么改造成配对反例。成本低，可解释性好，缺点是只动得了「数据里有的」。</p><p><strong>损失级注入。</strong> 对表征加约束项：有害区域高损失、目标概念的方向保持稳定。<a href="/llm/circuit-breaker">Circuit Breaker 课</a>已把表示重路由的损失与选层讲透，本课不重复；要点是它是谱系里最重的形态——把「读出后处置」换成「训练时改道」，推理期零开销，攻击者无法靠不加向量绕过。</p><p><strong>消融级注入。</strong> 先定位行为的中介方向，再直接投影消融。Arditi 等人 2024 年的结果是这条路的锚点：拒答行为在多个模型上主要由单一方向中介，消融它或加强它，拒答与越狱行为随之跨模型地移动。这是「理解工具即手术刀」的范例——方向既是机制结论，也是可操作的干预点。</p><p><span class="marginnote">「投影消融」做什么：把激活向量里沿「拒答方向」的分量直接减掉，等价于把向量投影到与该方向垂直的平面上。直觉类比音频均衡器：把某个频段拉到零，声音里属于那个频段的成分就听不见了。方向中介越集中（如拒答），这一刀切得越干净；能力损失也越小。</span></p>',11)),(e(),t(n,null,{default:a(()=>[l(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20READ%5B%22%E5%86%85%E9%83%A8%E8%AF%BB%E6%95%B0%EF%BC%9A%E7%89%B9%E5%BE%81%E7%94%BB%E5%83%8F%20%2F%20%E6%96%B9%E5%90%91%E5%AE%9A%E4%BD%8D%22%5D%20--%3E%20D1%7B%22%E6%B3%A8%E5%85%A5%E7%82%B9%22%7D%0A%20%20D1%20--%3E%7C%E6%95%B0%E6%8D%AE%7C%20DATA%5B%22%E7%AD%9B%E8%AF%AD%E6%96%99%EF%BC%9A%E5%89%94%E9%99%A4%E6%88%96%E6%94%B9%E9%80%A0%E9%AB%98%E8%AF%BB%E6%95%B0%E6%A0%B7%E6%9C%AC%E7%B0%87%22%5D%0A%20%20D1%20--%3E%7C%E6%8D%9F%E5%A4%B1%7C%20LOSS%5B%22%E8%A1%A8%E5%BE%81%E7%BA%A6%E6%9D%9F%EF%BC%9A%E6%9C%89%E5%AE%B3%E5%8C%BA%E9%AB%98%E6%8D%9F%E5%A4%B1%20%2F%20%E6%96%B9%E5%90%91%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20D1%20--%3E%7C%E6%B6%88%E8%9E%8D%7C%20ABL%5B%22%E6%8A%95%E5%BD%B1%E6%B6%88%E8%9E%8D%E4%B8%AD%E4%BB%8B%E6%96%B9%E5%90%91%22%5D%0A%20%20DATA%20--%3E%20RETRAIN%5B%22%E8%AE%AD%E7%BB%83%20%2F%20%E5%BE%AE%E8%B0%83%22%5D%0A%20%20LOSS%20--%3E%20RETRAIN%0A%20%20ABL%20--%3E%20RETRAIN%0A%20%20RETRAIN%20--%3E%20VAL%5B%22%E5%8F%8C%E9%AA%8C%E6%94%B6%EF%BC%9A%E8%A1%8C%E4%B8%BA%E5%9F%BA%E5%87%86%20%2B%20%E7%89%B9%E5%BE%81%E7%94%BB%E5%83%8F%20diff%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[B("表征级目标为什么难逃逸：攻击（或对抗压力）要找到"),A("strong",null,"不经过目标区域"),B("仍能解码出目标行为的续写路径，可搜索空间被约束压小；输出级目标只约束开场，表征原样保留续写能力——这是 "),A("a",{href:"/llm/circuit-breaker"},"Circuit Breaker"),B(" 机制分析的原样逻辑，适用于整个谱系。消融级为什么有效：单一方向中介说明行为在该方向上有充分读出，投影等价于掐断这条充分通路。")],-1)),E[5]||(E[5]=A("p",null,[B("但机制分析同时给出警示：充分通路被掐，"),A("strong",null,"平行通路"),B("仍在。消融或改道之后必须双验收——行为基准确认目标行为确实移动，特征画像 diff 确认没有新的异常读数冒出来。只有前者的引导训练，等于把问题从可读的子空间赶进不可读的子空间，监控反而失明。")],-1)),(e(),t(n,null,{default:a(()=>[l(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OUT%5B%22%E8%BE%93%E5%87%BA%E7%BA%A7%E7%9B%AE%E6%A0%87%EF%BC%9A%E5%8F%AA%E7%AE%A1%E4%BD%8F%E8%BE%93%E5%87%BA%22%5D%20--%3E%20E1%5B%22%E8%A1%A8%E5%BE%81%E4%BF%9D%E7%95%99%E7%BB%AD%E5%86%99%E8%83%BD%E5%8A%9B%EF%BC%8C%E6%8D%A2%E4%B8%AA%E5%BC%80%E5%9C%BA%E5%8D%B3%E7%BB%95%E8%BF%87%22%5D%0A%20%20REP%5B%22%E8%A1%A8%E5%BE%81%E7%BA%A7%E7%9B%AE%E6%A0%87%EF%BC%9A%E7%AE%A1%E4%BD%8F%E5%86%85%E9%83%A8%E5%8C%BA%E5%9F%9F%22%5D%20--%3E%20E2%5B%22%E6%94%BB%E5%87%BB%E9%A1%BB%E7%BB%95%E5%BC%80%E7%9B%AE%E6%A0%87%E5%8C%BA%E5%9F%9F%EF%BC%8C%E6%90%9C%E7%B4%A2%E7%A9%BA%E9%97%B4%E8%A2%AB%E5%8E%8B%E5%B0%8F%22%5D%0A%20%20ABL%5B%22%E6%B6%88%E8%9E%8D%EF%BC%9A%E6%8E%90%E6%96%AD%E5%85%85%E5%88%86%E9%80%9A%E8%B7%AF%22%5D%20--%3E%20P%5B%22%E5%B9%B3%E8%A1%8C%E9%80%9A%E8%B7%AF%E4%BB%8D%E5%9C%A8%EF%BC%8C%E7%9B%AE%E6%A0%87%E5%8F%AF%E8%83%BD%E6%8D%A2%E8%B7%AF%E8%A1%A8%E8%BE%BE%22%5D%0A%20%20P%20--%3E%20D%5B%22%E5%8F%8C%E9%AA%8C%E6%94%B6%EF%BC%9A%E8%A1%8C%E4%B8%BA%E5%9F%BA%E5%87%86%20%2B%20%E7%89%B9%E5%BE%81%E7%94%BB%E5%83%8F%20diff%22%5D%0A%20%20D%20--%3E%7Cdiff%20%E5%86%92%E5%87%BA%E6%96%B0%E8%AF%BB%E6%95%B0%7C%20W%5B%22%E7%9B%AE%E6%A0%87%E8%A2%AB%E8%B5%B6%E8%BF%9B%E4%B8%8D%E5%8F%AF%E8%AF%BB%E5%AD%90%E7%A9%BA%E9%97%B4%EF%BC%8C%E7%9B%91%E6%8E%A7%E5%A4%B1%E6%98%8E%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：「读数下降 = 目标消失了」。引导训练可能只是让模型改用未被监控的新表征形式表达同一目标——像把违规操作从摄像头正下方挪到监控死角，行为没变，只是看不见了。所以验收里特征画像 diff 与行为基准缺一不可：前者管「有没有换地方」，后者管「行为本身动没动」。</span></p><p><span class="marginnote">Arditi et al., 2024 的单一方向结果之所以重要：拒答不是遍布全网的分布式属性，一个方向承担了大部分中介——「消融一个方向」成了跨模型可复现的手术。同一把手术刀也是越狱工具，方向坐标的发布与复用要按攻击面管理。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>能力税是第一边界：表征约束蹭伤无害任务的概率随约束强度上升，保留损失的系数是主旋钮（Circuit Breaker 课的成对报告口径照用）。第二边界是表达的迁移：模型可能学会用新的、未被监控的表征形式表达同一目标——引导降低的是当前坐标下的读数，不是目标本身。第三，引导不是对齐证明：它改善的是特定概念的内部通路，与「模型可靠」之间隔着第 9 课要收拢的全部硬限。特征级损失的可扩展配方——哪些概念、哪几层、多强、怎么退火——目前仍是开放工程问题，没有公认配方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条注入点：数据级筛语料、损失级表征约束、消融级方向手术；重到轻依次是不可绕过性与审计成本。</li><li>表征级目标比输出级难逃逸：攻击必须找到绕开目标区域的续写路径。</li><li>引导后必须双验收：行为基准与特征画像 diff，缺一就是把问题赶进不可读子空间。</li><li>方向坐标既是机制结论也是手术刀与攻击面，发布按攻击面管理。</li><li>出处：Zou et al., 2023（rerouting）；Zou et al., 2024（Circuit Breakers）；Arditi et al., 2024（拒答的单方向中介）。</li></ul>',6))])}const h=o(D,[["render",p]]);export{g as __pageData,h as default};
